/**
 * P1.2 / B9 — shared rules for any action that writes its result to a NEW sheet
 * (reconciliations, cleaning results, reports). One place for:
 *   - collision-safe naming: a second run makes "Name (2)", never overwrites run 1
 *   - the one-line provenance note: "Generated by CELLIX from <sheet> on <date>"
 *
 * Output writers mark their CREATE_SHEET / ADD_SHEET with `uniqueName: true`;
 * `uniquifyOutputSheets` (called from finalizeActions) resolves the real names.
 */
import { SheetActionPayload } from '../types/sheet-actions.types';

const MAX_SHEET_NAME = 31;

/** First free "Name", "Name (2)", "Name (3)"… (case-insensitive, ≤31 chars). */
export function pickUniqueSheetName(desired: string, existing: Iterable<string>): string {
  const taken = new Set([...existing].map((n) => n.trim().toLowerCase()));
  const base = desired.trim().slice(0, MAX_SHEET_NAME) || 'Sheet';
  if (!taken.has(base.toLowerCase())) return base;
  for (let n = 2; n < 10_000; n += 1) {
    const suffix = ` (${n})`;
    const candidate = `${base.slice(0, MAX_SHEET_NAME - suffix.length).trimEnd()}${suffix}`;
    if (!taken.has(candidate.toLowerCase())) return candidate;
  }
  return `${base.slice(0, MAX_SHEET_NAME - 6)} (${Date.now() % 100000})`;
}

/**
 * Rename every colliding `uniqueName` sheet creation and re-point the actions that
 * target it. `relativeTo` / `copyFrom` name *other* sheets, so they are never rewritten.
 * Actions without `uniqueName` are untouched (existing "reuse the sheet" behaviour).
 */
export function uniquifyOutputSheets(
  actions: SheetActionPayload[],
  existingSheetNames: string[],
): SheetActionPayload[] {
  if (!actions.some((a) => a.uniqueName && (a.type === 'CREATE_SHEET' || a.type === 'ADD_SHEET'))) {
    return actions;
  }
  const taken = [...existingSheetNames];
  const renames = new Map<string, string>(); // lower-case requested name -> final name
  const out: SheetActionPayload[] = [];

  for (const action of actions) {
    const isCreate = action.type === 'CREATE_SHEET' || action.type === 'ADD_SHEET';
    if (isCreate && action.uniqueName) {
      const desired = String(action.name ?? action.sheetName ?? '');
      const finalName = pickUniqueSheetName(desired, taken);
      taken.push(finalName);
      renames.set(desired.trim().toLowerCase(), finalName);
      const rest = { ...action };
      delete rest.uniqueName;
      out.push({ ...rest, name: finalName, sheetName: finalName });
      continue;
    }
    const target = action.sheetName?.trim().toLowerCase();
    if (target && renames.has(target)) {
      out.push({ ...action, sheetName: renames.get(target)! });
    } else {
      out.push(action);
    }
  }
  return out;
}

/** "Generated by CELLIX from <sheet> on 05-Nov-2026" — the provenance line for output sheets. */
export function sourceNoteText(sourceSheet: string | undefined, at: Date | string = new Date()): string {
  if (typeof at === 'string') {
    const when = at.trim();
    if (when) return sourceSheet ? `Generated by CELLIX from ${sourceSheet} on ${when}` : `Generated by CELLIX on ${when}`;
    at = new Date();
  }
  const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  const date = `${String(at.getDate()).padStart(2, '0')}-${months[at.getMonth()]}-${at.getFullYear()}`;
  return sourceSheet
    ? `Generated by CELLIX from ${sourceSheet} on ${date}`
    : `Generated by CELLIX on ${date}`;
}
